(() => {
  const panel = document.querySelector('#data-tab-panel-bszml17zpd');
  // Get all direct text nodes and input names in document order
  const walker = document.createTreeWalker(panel, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT, {
    acceptNode: (n) => {
      if (n.nodeType === 3) return n.textContent.trim() ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_SKIP;
      return ['INPUT','SELECT','TEXTAREA','BUTTON'].includes(n.tagName) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_SKIP;
    }
  });
  const out = [];
  let n;
  while (n = walker.nextNode()) {
    if (n.nodeType === 3) out.push(`TEXT: ${n.textContent.trim().slice(0,60)}`);
    else if (n.tagName === 'BUTTON') out.push(`BUTTON: ${n.textContent.trim().slice(0,30)}`);
    else out.push(`${n.tagName}(${n.name || n.id || 'unnamed'})`);
  }
  return out.join('\n');
})()

